<?php
require_once dirname(__DIR__).'/src/bootstrap.php';if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}[$script,$email,$password,$name]=array_pad($argv,4,null);if(!$email||!$password||!$name){fwrite(STDERR,"Usage: php scripts/create_admin.php admin@example.com \"StrongPassword\" \"System Administrator\"\n");exit(1);}if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10){fwrite(STDERR,"Use a valid email and a password with at least 10 characters.\n");exit(1);}try{$stmt=db()->prepare("INSERT INTO users(role,full_name,email,password_hash,status,email_verified_at,mfa_enabled) VALUES('admin',?,?,?,'active',NOW(),1)");$stmt->execute([$name,strtolower($email),password_hash($password,PASSWORD_DEFAULT)]);echo "Admin created successfully. MFA is enabled; local mode displays a development sign-in code.\n";}catch(Throwable $e){fwrite(STDERR,$e->getMessage()."\n");exit(1);}
